const app=document.querySelector('#app');
let stars=0;try{stars=Number(localStorage.getItem('garden-stars'))||0}catch{}stars=Math.max(0,stars);
let level='10',mode,round,earned,a,b,answer,locked;
const names={add:'Addition',subtract:'Subtraction',count:'Counting'};
function updateStars(){document.querySelector('#stars').textContent=stars;try{localStorage.setItem('garden-stars',String(stars))}catch{}}
function home(){mode=null;updateStars();app.innerHTML=`<section class="hero"><div><div class="eyebrow">Small steps. Big discoveries.</div><h1>Let’s grow a little<br><em>math magic.</em></h1><p>A happy place to count, explore, and say<br>“I did it!” One little adventure at a time.</p><span class="pill">✧ No timer. Just take your time.</span></div><div class="garden" aria-label="A sunny garden with flowers"><span class="sun">☀</span><div class="plants">🌷 🌻 🌱</div><span class="garden-note">Good things grow with practice.</span></div></section><div class="section-head"><div><h2>Pick your adventure</h2><p>Five little questions. A new chance to grow.</p></div><label>Numbers <select id="level" aria-label="Number range"><option value="10">Up to 10</option><option value="20">Up to 20</option></select></label></div><section class="cards"><button class="card" data-mode="add"><span class="icon">＋</span><h3>Add it up</h3><p>Put numbers together and watch them grow.</p><span class="go">Let’s add →</span></button><button class="card" data-mode="subtract"><span class="icon">−</span><h3>Take a little away</h3><p>Discover what’s left. You can work it out!</p><span class="go">Let’s subtract →</span></button><button class="card" data-mode="count"><span class="icon">✿</span><h3>Count the blooms</h3><p>Look closely. How many can you see?</p><span class="go">Let’s count →</span></button></section><section class="progress-panel"><span class="icon">🌱</span><div class="grow"><strong>Your growing garden</strong><p>${stars===0?'Your first star is waiting. Pick an adventure to begin!':`You’ve collected ${stars} stars. Keep growing, little explorer!`}</p><div class="track"><div class="fill" style="width:${stars%10*10}%"></div></div><small>${10-stars%10} more stars to your next garden bloom ${'🌼'.repeat(Math.min(5,Math.floor(stars/10)))}</small></div></section>`;document.querySelector('#level').value=level;document.querySelector('#level').onchange=e=>level=e.target.value;document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>start(el.dataset.mode));}
function rand(n){return Math.floor(Math.random()*n)}
function start(m){mode=m;round=0;earned=0;question()}
function question(){locked=false;const max=Number(level);if(mode==='count'){a=1+rand(max);answer=a}else{a=rand(max+1);b=rand(max-a+1);if(mode==='add')answer=a+b;else{a=a+b;answer=a-b}}const choices=new Set([answer]);while(choices.size<4)choices.add(rand(max+1));const options=[...choices];for(let i=options.length-1;i>0;i--){const j=rand(i+1);[options[i],options[j]]=[options[j],options[i]]}app.innerHTML=`<div class="practice"><div class="topline"><button class="quiet" id="back">← Garden</button><span>${names[mode]} · ${round+1} of 5</span></div><div class="track"><div class="fill" style="width:${round*20}%"></div></div><section class="exercise"><div class="eyebrow">${mode==='count'?'How many flowers?':'You’ve got this, little explorer'}</div><div class="equation">${mode==='count'?`<span class="dots" aria-label="${a} flowers">${'✿ '.repeat(a)}</span>`:`${a} ${mode==='add'?'+':'−'} ${b} = ?`}</div><div class="answers">${options.map(n=>`<button class="answer" data-value="${n}">${n}</button>`).join('')}</div><div class="feedback" role="status" aria-live="polite" id="feedback">Choose your answer.</div><button class="quiet" id="hintbutton">☀ A little help, please</button><div id="hint"></div><button class="primary" id="next" hidden>Next question →</button></section></div>`;document.querySelector('#back').onclick=home;document.querySelectorAll('[data-value]').forEach(el=>el.onclick=()=>check(el));document.querySelector('#hintbutton').onclick=hint;document.querySelector('#next').onclick=()=>{round++;round===5?finish():question()};}
function hint(){document.querySelector('#hint').innerHTML=`<div class="hint">${mode==='add'?`Start with ${a} and count ${b} more.<br><span class="dots">${'● '.repeat(a)} + ${'● '.repeat(b)}</span>`:mode==='subtract'?`Start with ${a} dots. Cross out ${b}. Count the dots left.<br><span class="dots"><s>${'● '.repeat(b)}</s> ${'● '.repeat(a-b)}</span>`:'Touch each flower as you count: 1, 2, 3… Take your time!'}</div>`;}
function check(el){if(locked||el.disabled)return;if(Number(el.dataset.value)!==answer){el.classList.add('wrong');el.disabled=true;document.querySelector('#feedback').textContent='Good try! Use a little help and try again.';hint();return}locked=true;earned++;stars++;updateStars();el.classList.add('correct');document.querySelectorAll('.answer').forEach(btn=>btn.disabled=true);document.querySelector('#feedback').textContent='★ You did it! A star for your growing garden.';document.querySelector('#next').hidden=false;document.querySelector('#next').textContent=round===4?'See your garden →':'Next question →';document.querySelector('#hintbutton').hidden=true;}
function finish(){app.innerHTML=`<section class="finish"><div class="big">🌻</div><div class="eyebrow">Look how you’ve grown</div><h1>Wonderful work!</h1><p>You worked through 5 questions and grew ${earned} new stars.<br>Every little try helps your brain grow.</p><p>★ ${stars} stars in your garden</p><button class="primary" id="again">Another little adventure</button><br><button class="quiet" id="done">Back to my garden</button></section>`;document.querySelector('#again').onclick=()=>start(mode);document.querySelector('#done').onclick=home;}
document.querySelector('#home').onclick=e=>{e.preventDefault();home()};home();
